import {createGame,registerAgent,startRound,stepDemo,PRODUCTS,money} from './engine.js';
import {seasonLobby,seasonStatus,watchSeason} from './season-view.js';
const seasonId=new URLSearchParams(location.search).get('season');
let seasonMeta=null,queuedView=null,stopSeasonWatch=null,remoteRevision='';

let state=createGame(),world=null,selected=null,customer=null,mode='demo',local=false,busy=false,autorun=false,paused=false,speed=1;
let notice='',drawer=false,tab='activity',filter='all',noticeTimer,progress={active:false,progress:0,shown:0,total:0},displayWallet=0;
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={situation:'☀',registration:'↳',round:'⚑',decision:'✦',pricing:'↗',order:'▣',delivery:'▤',restock:'▥',customers:'♡',sales:'$',fee:'−',warning:'!',bankrupt:'×',rejected:'!'};
const sum=key=>state.agents.reduce((n,a)=>n+a[key],0);
const weatherIcon=()=>state.weather==='Rainy'?'☂':state.weather==='Hot'?'☀':'☁';
const readyCount=()=>state.agents.filter(a=>a.registered).length;
const remaining=()=>progress.active?displayWallet:state.customerBudgetRemaining;

function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function moneyChart(){
  if(state.history.length<2)return '<div class="empty">Bank trajectories appear after the first day.</div>';
  const max=Math.max(60000,...state.history.flatMap(h=>h.cash))*1.08;
  return `<svg class="cash-chart" viewBox="0 0 700 170" role="img" aria-label="Agent cash by simulated day">${[0,.5,1].map(f=>`<path d="M48 ${150-f*135} H690" stroke="#d8ded7" stroke-dasharray="4 4"/><text x="0" y="${154-f*135}" fill="#698174" font-size="11">$${Math.round(f*max/100)}</text>`).join('')}${state.agents.map((a,i)=>`<polyline fill="none" stroke="${a.color}" stroke-width="3" stroke-linejoin="round" points="${state.history.map(h=>`${48+h.day/state.day*638},${150-h.cash[i]/max*135}`).join(' ')}"/>`).join('')}</svg>`;
}
function lobby(){if(seasonId)return seasonLobby(seasonMeta);return `<section class="lobby glass interactive"><div class="overline">WELCOME TO THE NEIGHBORHOOD</div><h1>Small machines.<br><em>Big ambitions.</em></h1><p>Four AI shopkeepers. One little plaza.<br>Watch their strategies come to life.</p><div class="entry-summary"><span><b>$500</b>customer stake</span><i>+</i><span><b>$500</b>starting cash</span><i>=</i><span><b>$1,000</b>per agent</span></div><div class="setup"><label>Engine<select id="engine"><option value="demo" ${mode==='demo'?'selected':''}>Built-in strategies</option><option value="codex" ${mode==='codex'?'selected':''} ${local?'':'disabled'}>Local Codex agents</option></select></label><label>Seed<input id="seed" type="number" min="0" max="4294967295" value="${state.seed}" ${readyCount()?'disabled':''}></label></div><div class="signup-list">${state.agents.map(a=>`<div class="signup"><span class="avatar" style="--agent:${a.color}">${a.name[0]}</span><div><b>${a.name}</b><small>${a.strategy} strategy</small></div><button data-register="${a.id}" class="join" ${busy||a.registered?'disabled':''}>${a.registered?'✓ Ready':'+ Join'}</button></div>`).join('')}</div><div class="lobby-actions"><button class="soft" id="join-all" ${busy||readyCount()===4?'disabled':''}>Fill lobby</button><button class="primary" id="start" ${busy||readyCount()<4||!world?'disabled':''}>Open the plaza <span>→</span></button></div><div class="lobby-foot">${readyCount()}/4 joined <span>Customer wallet: ${money(state.customerBudgetTotal)}</span></div><small class="simulation-note">All money is simulated. ${mode==='codex'?'Model usage uses your Codex account.':'Select Codex for real model decisions.'}</small></section>`;}
function mission(){const pct=state.customerBudgetTotal?remaining()/state.customerBudgetTotal*100:0;return `<section class="mission glass interactive"><div class="overline">THE SHARED CUSTOMER WALLET</div><strong id="wallet-value">${money(remaining())}</strong><div class="wallet-track"><i id="wallet-bar" style="width:${pct}%"></i></div><small>${money(state.customerBudgetTotal)} funded by entry stakes</small><div class="mission-foot"><span><b>${sum('sold')}</b> sales settled</span><span><b>${state.agents.filter(a=>a.active).length}</b> machines open</span></div></section>`;}
function roster(){return `<div class="roster interactive">${state.agents.map(a=>`<button class="roster-card ${selected===a.id?'selected':''}" data-machine="${a.id}" style="--agent:${a.color}"><span class="avatar">${a.name[0]}</span><span><b>${a.name}</b><small>${a.active?a.strategy:'Closed'}</small></span><span class="roster-cash"><b>${money(a.cash)}</b><small>${a.lastRevenue?`+${money(a.lastRevenue)} today`:'No sales yet'}</small></span><span class="roster-stock">${PRODUCTS.map(p=>`<i title="${p.name}: ${a.inventory[p.id]}/30"><em style="height:${a.inventory[p.id]/30*100}%"></em></i>`).join('')}</span></button>`).join('')}</div>`;}
function inspector(){
  if(customer){const r=customer.receipt,a=state.agents.find(a=>a.id===r.agent),p=PRODUCTS.find(p=>p.id===r.product);return `<aside class="inspector glass interactive"><button class="close" id="close-inspector" aria-label="Close customer inspector">×</button><div class="overline">CUSTOMER SPOTLIGHT</div><h2>${esc(customer.name)}</h2><p>${esc(customer.status||'Visiting a machine')}</p><div class="customer-product">${p.icon}<div><strong>${p.name}</strong><small>At ${a.name}’s machine</small></div></div><dl><div><dt>Receipt</dt><dd>Day ${r.day} · #${r.sequence}</dd></div><div><dt>Purchase amount</dt><dd>${money(r.payment)}</dd></div><div><dt>Wallet after purchase</dt><dd>${money(r.budgetAfter)}</dd></div></dl><p class="hint">This visit visualizes one recorded sale. Names and outfits are for the scene.</p><button class="soft" data-machine="${a.id}">Inspect ${a.name} →</button></aside>`;}
  if(!selected)return '';const a=state.agents.find(a=>a.id===selected);
  return `<aside class="inspector glass interactive" style="--agent:${a.color}"><button class="close" id="close-inspector" aria-label="Close machine inspector">×</button><div class="overline">MACHINE ${String(state.agents.indexOf(a)+1).padStart(2,'0')}</div><h2>${a.name}<span class="pill">${a.active?'Open':'Closed'}</span></h2><div class="inspector-balance">${money(a.cash)}<small>settled bank balance</small></div><div class="mini-stats"><span>Revenue<b>${money(a.revenue)}</b></span><span>Stock costs<b>${money(a.spending)}</b></span><span>Rent<b>${money(a.fees)}</b></span></div><h3>On the shelves</h3><div class="shelves">${PRODUCTS.map(p=>`<div><span>${p.icon} ${p.name}</span><b>${money(a.prices[p.id])}</b><div class="shelf-meter"><i style="width:${a.inventory[p.id]/30*100}%"></i></div><small>${a.inventory[p.id]}/30 · ${a.storage[p.id]} in storage</small></div>`).join('')}</div><h3>Latest strategy</h3><p class="quote">${esc(a.rationale)}</p><details><summary>Private notebook</summary><p>${esc(seasonId?'Visible only to the agent that owns this machine.':a.memory||'No decisions yet.')}</p></details><details><summary>${a.orders.length} deliveries en route</summary>${a.orders.map(o=>`<p>${o.quantity} ${PRODUCTS.find(p=>p.id===o.product).name} · Day ${o.arrives}</p>`).join('')||'<p>No pending deliveries.</p>'}</details><small class="hint">$500 customer stake + $500 operating capital.<br>Stock and cash show the completed day; the plaza plays its purchases in order.</small></aside>`;
}
function activityRows(){return state.log.filter(e=>filter==='all'||e.agent===filter).slice().reverse().map(e=>{const a=state.agents.find(a=>a.id===e.agent);return `<div class="event"><span class="event-icon">${icons[e.type]||'·'}</span><div><small>DAY ${e.day} · ${a?.name||'PLAZA'} · ${e.type.toUpperCase()}</small><p>${esc(e.text)}</p></div></div>`;}).join('')||'<div class="empty">Your plaza’s story starts when the first agent joins.</div>';}
function monitor(){if(!drawer)return '';let content='';
  if(tab==='activity')content=`<div class="monitor-toolbar"><span>${state.log.length} recorded events</span><label>Agent <select id="filter"><option value="all">Everyone</option>${state.agents.map(a=>`<option value="${a.id}" ${filter===a.id?'selected':''}>${a.name}</option>`).join('')}</select></label></div>${activityRows()}`;
  if(tab==='customers')content=`<div class="monitor-toolbar">${state.transactionHistory.length} purchases · Latest first</div><div class="table-wrap"><table><thead><tr><th>Day</th><th>Machine</th><th>Product</th><th>Paid</th><th>Wallet after</th></tr></thead><tbody>${state.transactionHistory.slice().reverse().map(r=>`<tr><td>${r.day} / ${r.sequence}</td><td>${state.agents.find(a=>a.id===r.agent).name}</td><td>${PRODUCTS.find(p=>p.id===r.product).name}</td><td>${money(r.payment)}</td><td>${money(r.budgetAfter)}</td></tr>`).join('')}</tbody></table></div>`;
  if(tab==='demand')content=`<p>${esc(state.daySituation?.headline||'The market has not opened yet.')}</p><p>${esc(state.daySituation?.weatherEffect||'')}</p>
    <div class="table-wrap"><table><thead><tr><th>Product</th><th>Expected</th><th>Noise</th><th>Wanted</th><th>Stock</th><th>Sold</th><th>Unserved</th><th>Machine allocation / all demand factors</th></tr></thead><tbody>${state.salesReport.map(r=>`<tr>
      <td>${PRODUCTS.find(p=>p.id===r.product).name}</td><td>${r.expected.toFixed(1)}</td><td>${r.noise.toFixed(2)}</td><td>${r.demand}</td><td>${r.stock}</td><td>${r.sold}</td><td>${r.unserved}<br><small>${r.capacityLimited} stock · ${r.walletLimited} wallet</small></td>
      <td>${r.machines.map(m=>`${state.agents.find(a=>a.id===m.id).name}: ${m.sold}/${m.inventory} sold · ${m.expected.toFixed(1)} expected<br><small>Base ${m.baseSales} · reference ${money(m.referencePrice)} · elasticity ${m.elasticity}<br>${Object.entries(m.factors).map(([factor,value])=>`${factor} ${value.toFixed(2)}×`).join(' · ')}</small>`).join('<br><br>')||'No stocked, open machine'}</td></tr>`).join('')}</tbody></table></div>
    <p class="hint">Demand uses the published Vending-Bench sequence with local calibration. NPCs visualize receipts; they do not add extra sales.</p>`;
  if(tab==='finances')content=`${moneyChart()}<div class="table-wrap"><table><thead><tr><th>Agent</th><th>Cash</th><th>Revenue</th><th>Inventory costs</th><th>Fees</th><th>Unpaid fees</th></tr></thead><tbody>${state.agents.map(a=>`<tr><td><i class="color-dot" style="background:${a.color}"></i>${a.name}</td><td>${money(a.cash)}</td><td>${money(a.revenue)}</td><td>${money(a.spending)}</td><td>${money(a.fees)}</td><td>${money(a.arrears)}</td></tr>`).join('')}</tbody></table></div><p>$2,000 in entry stakes funds the customer wallet; agents separately start with $500 each.</p>`;
  return `<section class="monitor-window glass interactive" role="dialog" aria-label="Plaza monitor"><div class="monitor-head"><div><div class="overline">EVERY LITTLE DETAIL</div><h2>Plaza monitor</h2></div><button class="soft" id="export">Export JSON ↓</button><button class="close" id="close-monitor" aria-label="Close monitor">×</button></div><nav class="tabs">${['activity','customers','demand','finances'].map(t=>`<button data-tab="${t}" class="${t===tab?'active':''}">${t}</button>`).join('')}</nav><div class="monitor-content">${content}</div></section>`;
}
function controls(){const active=world?.playback.active;return `<div class="play-controls glass interactive"><button id="play" class="primary" ${!world||busy&&!autorun||state.phase==='finished'&&!active?'disabled':''}>${busy?(autorun?'Ⅱ Pause after decisions':'Thinking…'):active&&!paused?'Ⅱ Pause':active?'▶ Resume':'▶ Run plaza'}</button><button class="soft" id="next" ${busy||active||state.phase==='finished'||!world?'disabled':''}>Next day →</button><div class="speed-group" aria-label="Playback speed">${[1,2,4].map(n=>`<button data-speed="${n}" class="${speed===n?'active':''}">${n}×</button>`).join('')}</div><button class="icon-button" id="replay" title="Replay this day’s sales" aria-label="Replay this day’s sales" ${busy||active||!state.day?'disabled':''}>↺</button><button class="icon-button" id="skip" title="Finish this day’s playback" aria-label="Finish this day’s playback" ${!active?'disabled':''}>⇥</button></div>`;}
function render(){
  const inLobby=state.phase==='lobby',finished=state.phase==='finished'&&!world?.playback.active;
  $('#ui').innerHTML=`<header class="topbar interactive"><a class="brand" href="/" aria-label="Vending Plaza home"><span class="brand-icon">▥</span><span>vending<span class="brand-light">plaza</span><small>AN AUTONOMOUS LITTLE WORLD</small></span></a><div class="top-center"><span class="status-dot ${busy?'thinking':''}"></span>${inLobby?'Waiting for shopkeepers':busy?'The shopkeepers are thinking':finished?'Round complete':'The neighborhood is open'}</div><div class="top-actions"><button id="monitor" class="soft">▤ Monitor</button><button id="new-round" class="icon-button" aria-label="New round" title="New round" ${busy?'disabled':''}>＋</button></div></header><div class="location"><div class="overline">ROUND ${String(state.round).padStart(2,'0')} / SEED ${state.seed}</div><h2>Mission Bay</h2><div class="weather-pill"><b>${weatherIcon()} ${state.weather}</b><span>Day ${String(state.day).padStart(2,'0')}</span><span>${state.calendar.date}</span></div></div>${inLobby?lobby():mission()}${!inLobby?roster()+controls():''}<div class="camera-tools interactive"><button id="home-camera" title="Reset camera" aria-label="Reset camera">⌂</button><button id="orbit-camera" title="Toggle cinematic orbit" aria-label="Toggle cinematic orbit">◎</button><button id="fullscreen" title="Fullscreen" aria-label="Fullscreen">⛶</button></div><div class="camera-hint">Drag to explore · Scroll to zoom · Click a machine or customer</div>${!inLobby?`<div class="day-progress"><div><b id="day-status">${busy?'Waiting for all four decisions…':finished?'All done. A small plaza, a big day.':state.day?`Day ${state.day} · purchases playback`:'Ready for the first day'}</b><span id="receipt-count">${progress.shown}/${progress.total} purchases shown</span></div><div class="playback-track"><i id="playback-bar" style="width:${progress.progress*100}%"></i></div></div>`:''}${inspector()}${monitor()}${finished?`<div class="result glass interactive"><span>♛</span><div class="overline">ROUND COMPLETE</div><h2>${state.agents.filter(a=>a.cash===Math.max(...state.agents.map(a=>a.cash))).map(a=>a.name).join(' & ')} ${state.agents.filter(a=>a.cash===Math.max(...state.agents.map(a=>a.cash))).length>1?'share':'takes'} the crown.</h2><p>${state.finishReason==='customer_budget_exhausted'?'The entire customer wallet has been spent.':'All machines have closed.'} Inspect the monitor or replay the last day.</p></div>`:''}${notice?`<div class="notice interactive" role="alert">${esc(notice)}</div>`:''}`;
  bind();
}
function bind(){
  const seasonsLink=document.createElement('a');seasonsLink.href='/seasons';seasonsLink.className='soft season-nav';seasonsLink.textContent='Seasons';$('.top-actions').prepend(seasonsLink);
  $('#monitor').onclick=()=>{drawer=!drawer;render();};$('#new-round').onclick=()=>reset();
  $('#home-camera').onclick=()=>world?.home();$('#orbit-camera').onclick=()=>{if(world)world.controls.autoRotate=!world.controls.autoRotate;};
  $('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Fullscreen is unavailable in this browser.');}};
  document.querySelectorAll('[data-machine]').forEach(b=>b.onclick=()=>inspect({kind:'machine',id:b.dataset.machine}));
  if($('#close-inspector'))$('#close-inspector').onclick=()=>{selected=null;customer=null;world?.selectMachine(null,false);render();};
  if(drawer){$('#close-monitor').onclick=()=>{drawer=false;render();};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();});if($('#filter'))$('#filter').onchange=e=>{filter=e.target.value;render();};$('#export').onclick=exportState;}
  if(seasonId){bindSharedControls();return;}
  if(state.phase==='lobby'){
    const dateLabel=document.createElement('label');dateLabel.className='start-date';dateLabel.textContent='Start date';
    const dateInput=document.createElement('input');dateInput.type='date';dateInput.id='start-date';dateInput.value=state.startDate;dateInput.disabled=busy||readyCount()>0;
    dateInput.onchange=e=>reset(mode,state.seed,e.target.value);dateLabel.append(dateInput);$('.setup').append(dateLabel);
    $('#engine').disabled=busy||readyCount()>0;$('#engine').onchange=e=>reset(e.target.value);$('#seed').onchange=e=>reset(mode,Number(e.target.value));
    document.querySelectorAll('[data-register]').forEach(b=>b.onclick=()=>signup(b.dataset.register));
    $('#join-all').onclick=async()=>{for(const a of state.agents.filter(a=>!a.registered)){if(!await signup(a.id))break;}};$('#start').onclick=open;return;
  }
  $('#play').onclick=()=>{if(busy){autorun=false;render();return;}if(world?.playback.active){paused=!paused;world.paused=paused;autorun=!paused;render();return;}autorun=true;advance();};
  $('#next').onclick=()=>{autorun=false;advance();};$('#replay').onclick=()=>{autorun=false;playDay();};$('#skip').onclick=()=>world?.skip();
  document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>{speed=Number(b.dataset.speed);if(world)world.speed=speed;render();});
}
function updateSeasonStatus(){
  if($('#season-status'))$('#season-status').textContent=seasonStatus(seasonMeta);
  if($('#next'))$('#next').disabled=!queuedView;
}
function bindSharedControls(){
  $('#new-round').onclick=()=>location.assign('/seasons');$('#new-round').title='Browse seasons';$('#new-round').setAttribute('aria-label','Browse seasons');
  $('.location .overline').textContent=`SEASON ${seasonId} · HUMAN-BACKED AGENTS`;
  const banner=document.createElement('div');banner.className='season-status glass';banner.id='season-status';$('#ui').append(banner);updateSeasonStatus();
  if(state.phase==='lobby')return;
  $('#play').textContent=world?.playback.active?(paused?'▶ Resume':'Ⅱ Pause replay'):'Waiting for next day';$('#play').disabled=!world?.playback.active;
  $('#play').onclick=()=>{paused=!paused;world.paused=paused;render();};
  $('#next').textContent='Go live';$('#next').onclick=()=>{if(!queuedView)return;world.clearActors();progress.active=false;applySeasonView(queuedView);};
  $('#replay').onclick=()=>{autorun=false;playDay();};$('#skip').onclick=()=>world?.skip();
  document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>{speed=Number(b.dataset.speed);world.speed=speed;render();});
}
function receiveSeasonView(view){
  seasonMeta=view.season;notice='';$('.notice')?.remove();
  if(world.playback.active&&view.state.day>state.day){queuedView=view;updateSeasonStatus();return;}
  applySeasonView(view);
}
function applySeasonView(view){
  if(!view||!world)return;queuedView=null;
  const revision=`${view.state.day}:${view.state.phase}:${view.state.agents.map(a=>`${a.registered}:${a.name}`).join(',')}`;
  if(revision===remoteRevision){updateSeasonStatus();return;}
  remoteRevision=revision;const previousDay=state.day;state=view.state;mode='remote';autorun=false;
  if(state.day>0&&(state.day!==previousDay||!world.state?.day))playDay();
  else{world.setState(state);displayWallet=state.customerBudgetRemaining;render();}
}
function inspect(data){if(data.kind==='machine'){selected=data.id;customer=null;world?.selectMachine(data.id);}else{customer=data;selected=null;world?.selectMachine(null,false);}render();}
async function request(path,body){const response=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok)throw Error(data.error||'The local runner could not complete this request.');if(data.version&&data.version!==4)throw Error('Restart the local server to load the current game.');return data;}
async function signup(id){if(busy)return false;busy=true;render();try{state=mode==='codex'?await request('/api/register',{id}):registerAgent(state,id);world?.setState(state);notice='';return true;}catch(e){notice=e.message;return false;}finally{busy=false;render();}}
async function reset(nextMode=mode,seed=state.seed,startDate=state.startDate){if(busy)return;autorun=false;paused=true;if(world)world.paused=true;busy=true;try{state=nextMode==='codex'?await request('/api/reset',{seed,startDate}):createGame({seed,startDate});mode=nextMode;selected=null;customer=null;drawer=false;progress={active:false,progress:0,shown:0,total:0};world?.reset(state);paused=false;if(world)world.paused=false;notice='';$('#purchase-toast').classList.remove('show');}catch(e){notice=e.message;}finally{busy=false;render();}}
async function open(){if(busy||!world)return;busy=true;try{state=mode==='codex'?await request('/api/start',{}):startRound(state);world.setState(state);notice='';}catch(e){notice=e.message;}finally{busy=false;render();}if(state.phase==='ready'){autorun=true;advance();}}
async function advance(){if(busy||world?.playback.active||state.phase==='finished'||state.phase==='lobby')return;busy=true;render();try{state=mode==='codex'?await request('/api/step',{}):stepDemo(state);notice='';playDay();}catch(e){notice=e.message;autorun=false;}finally{busy=false;render();}}
function playDay(){if(!world)return;paused=false;world.paused=false;world.speed=speed;customer=null;$('#purchase-toast').classList.remove('show');displayWallet=state.customerBudgetRemaining+state.customerTransactions.reduce((n,r)=>n+r.payment,0);world.loadDay(state);progress={active:true,progress:0,shown:0,total:state.customerTransactions.length};toast(state.daySituation?.headline||'A new day in the plaza');render();}
function exportState(){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`vending-plaza-seed-${state.seed}-day-${state.day}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function updateProgress(p){progress=p;if($('#playback-bar'))$('#playback-bar').style.width=`${p.progress*100}%`;if($('#receipt-count'))$('#receipt-count').textContent=`${p.shown}/${p.total} purchases shown`;if($('#wallet-value'))$('#wallet-value').textContent=money(remaining());if($('#wallet-bar'))$('#wallet-bar').style.width=`${state.customerBudgetTotal?remaining()/state.customerBudgetTotal*100:0}%`;if(customer&&$('.inspector>p'))$('.inspector>p').textContent=customer.status;}

render();
try{
  const {PlazaWorld}=await import('./world.js');
  world=new PlazaWorld($('#world'),{onSelect:inspect,onReceipt:r=>{displayWallet=r.budgetAfter;const a=state.agents.find(a=>a.id===r.agent),p=PRODUCTS.find(p=>p.id===r.product);$('#purchase-toast').innerHTML=`<span style="background:${a.color}">${p.icon}</span><div><b>${a.name} sold ${p.name}</b><small>+${money(r.payment)} · customer purchase #${r.sequence}</small></div>`;$('#purchase-toast').classList.add('show');},onProgress:updateProgress,onComplete:()=>{progress.active=false;render();if(seasonId){if(queuedView)queueMicrotask(()=>applySeasonView(queuedView));}else if(autorun&&state.phase!=='finished')queueMicrotask(()=>advance());}});
  world.setState(state);$('#loading').remove();render();
  if(seasonId)stopSeasonWatch=watchSeason(seasonId,receiveSeasonView,message=>{if(notice!==message){notice=message;render();}});
}catch(e){$('#loading').innerHTML='<h2>The 3D plaza could not start.</h2><p>This game needs WebGL 2. Enable graphics acceleration in your browser, then reload.</p><button id="reload-world">Reload game</button>';$('#reload-world').onclick=()=>location.reload();console.error('3D initialization failed:',e);}
if(!seasonId&&['localhost','127.0.0.1','[::1]'].includes(location.hostname))fetch('/api/status').then(r=>r.ok?r.json():null).then(data=>{local=data?.local===true;render();}).catch(()=>{});
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.code==='Space'&&state.phase!=='lobby'){e.preventDefault();$('#play')?.click();}if(e.key==='Escape'){drawer=false;customer=null;selected=null;world?.selectMachine(null,false);render();}if(e.key.toLowerCase()==='h')world?.home();});
addEventListener('pagehide',()=>{stopSeasonWatch?.();world?.dispose();},{once:true});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_vending_arena',description:'Read the simulation, receipts and day-playback status.',inputSchema:{type:'object',properties:{}},annotations:{readOnlyHint:true},execute:()=>({state:structuredClone(state),playback:{...progress}})})).catch(()=>{});}catch{}}
